document.getElementById('pdfForm').addEventListener('submit', function(e) {
    e.preventDefault();

    const v = (id) => { const el = document.getElementById(id); return el ? el.value.trim() : ''; };
    const checked = (id) => { const el = document.getElementById(id); return el ? el.checked : false; };

    const fmtDate = (d) => {
      if (!d) return '—';
      const [yr, m, day] = d.split('-');
      return `${day}/${m}/${yr}`;
    };
    const fmtMoney = (val) => {
      if (!val) return '—';
      return 'R$ ' + parseFloat(val).toFixed(2).replace('.', ',');
    };

    // Coletar bagagens dinâmicas
    const bagagens = [];
    document.querySelectorAll('.bagagem-item').forEach((item) => {
      const idMatch = item.id.match(/bagagem-item-(\d+)/);
      if (!idMatch) return;
      const id = idMatch[1];
      bagagens.push({
        tipo:  v('bagagem_tipo_'  + id),
        qtd:   v('bagagem_qtd_'   + id) || '0',
        valor: v('bagagem_valor_' + id),
      });
    });

    const { jsPDF } = window.jspdf;
    const doc = new jsPDF({ unit: 'mm', format: 'a4' });

    const W = 210;
    const margin = 18;
    let y = 0;

    const blue    = [0, 151, 178];
    const white   = [255, 255, 255];
    const light   = [240, 244, 248];
    const dark    = [26, 32, 44];
    const muted   = [100, 116, 139];
    const divider = [226, 232, 240];

    const LOGO_VM    = 'data:image/png;base64,';
    const LOGO_GOL   = 'data:image/png;base64,';
    const LOGO_AZUL  = 'data:image/png;base64,';
    const LOGO_LATAM = 'data:image/png;base64,';

    const ciaLogos = {
      'Gol':   { img: LOGO_GOL,   w: 34.4, h: 14 },
      'Azul':  { img: LOGO_AZUL,  w: 63.0, h: 42 },
      'Latam': { img: LOGO_LATAM, w: 60.0, h: 14 },
    };

    function setFont(size, style = 'normal', color = dark) {
      doc.setFontSize(size);
      doc.setFont('helvetica', style);
      doc.setTextColor(...color);
    }

    function sectionTitle(label, yPos) {
      yPos = checkPage(yPos, 20);
      doc.setFillColor(...light);
      doc.rect(margin, yPos, W - margin * 2, 7, 'F');
      doc.setFillColor(...blue);
      doc.rect(margin, yPos, 3, 7, 'F');
      setFont(8, 'bold', blue);
      doc.text(label.toUpperCase(), margin + 6, yPos + 4.8);
      return yPos + 11;
    }

    function cell(label, value, yPos, x, colW) {
      setFont(7.5, 'normal', muted);
      doc.text(label, x, yPos);
      setFont(9, 'bold', dark);
      const maxW = colW - 2;
      const lines = doc.splitTextToSize(value || '—', maxW);
      doc.text(lines[0], x, yPos + 5);
    }

    function twoRows(label1, val1, label2, val2, yPos) {
      yPos = checkPage(yPos);
      const colW = (W - margin * 2) / 2;
      cell(label1, val1, yPos, margin, colW);
      if (label2) cell(label2, val2, yPos, margin + colW, colW);
      return yPos + 11;
    }

    function fourCols(l1, v1, l2, v2, l3, v3, l4, v4, yPos) {
      yPos = checkPage(yPos);
      const colW = (W - margin * 2) / 4;
      cell(l1, v1, yPos, margin, colW);
      if (l2) cell(l2, v2, yPos, margin + colW, colW);
      if (l3) cell(l3, v3, yPos, margin + colW * 2, colW);
      if (l4) cell(l4, v4, yPos, margin + colW * 3, colW);
      return yPos + 11;
    }

    function dividerLine(yPos) {
      doc.setDrawColor(...divider);
      doc.setLineWidth(0.3);
      doc.line(margin, yPos, W - margin, yPos);
      return yPos + 4;
    }

    const pageH = 297;
    const pageLimit = pageH - 18;

    function checkPage(yPos, needed = 14) {
      if (yPos + needed > pageLimit) {
        doc.addPage();
        return 14;
      }
      return yPos;
    }

    // ── HEADER ──────────────────────────────────────────────────────────────
    const cia = v('cia_aerea');
    const ciaInfo = ciaLogos[cia];

    doc.setFillColor(...blue);
    doc.rect(0, 0, W, 38, 'F');

    doc.addImage(LOGO_VM, 'PNG', margin, 2, 32, 32);

    setFont(8, 'normal', [180, 200, 240]);
    const now = new Date();
    doc.text(`Emitido em: ${now.toLocaleDateString('pt-BR')} ${now.toLocaleTimeString('pt-BR', {hour:'2-digit', minute:'2-digit'})}`, margin + 32, 23);

    if (ciaInfo) {
      const ciaX = W - margin - ciaInfo.w;
      const ciaY = (38 - ciaInfo.h) / 2;
      doc.addImage(ciaInfo.img, 'PNG', ciaX, ciaY, ciaInfo.w, ciaInfo.h);
    } else {
      setFont(10, 'bold', white);
      doc.text(cia || '—', W - margin, 14, { align: 'right' });
    }

    y = 46;

    // ── VOO IDA ─────────────────────────────────────────────────────────────
    y = sectionTitle('Voo - Ida', y);
    y = twoRows('Origem', v('origem_ida'), 'Destino', v('destino_ida'), y);
    y = fourCols('Data', fmtDate(v('data_ida')), 'Horário', v('horario_ida') || '—', 'Número do Voo', v('numero_voo_ida'), 'Duração', v('duracao_voo_ida') || '—', y);
    if (checked('conexao_ida')) {
      y = fourCols('Conexão', 'Sim', 'Paradas', v('paradas_ida') || '1', 'Passageiros', v('qtd_pessoas_ida') || '1', '', '', y);
    } else {
      y = twoRows('Conexão', 'Não  |  Voo direto', 'Passageiros', v('qtd_pessoas_ida') || '1', y);
    }
    y = dividerLine(y);

    // ── VOO VOLTA ────────────────────────────────────────────────────────────
    y = sectionTitle('Voo - Volta', y);
    y = twoRows('Origem', v('origem_volta'), 'Destino', v('destino_volta'), y);
    y = fourCols('Data', fmtDate(v('data_volta')), 'Horário', v('horario_volta') || '—', 'Número do Voo', v('numero_voo_volta'), 'Duração', v('duracao_voo_volta') || '—', y);
    if (checked('conexao_volta')) {
      y = fourCols('Conexão', 'Sim', 'Paradas', v('paradas_volta') || '1', 'Passageiros', v('qtd_pessoas_volta') || '1', '', '', y);
    } else {
      y = twoRows('Conexão', 'Não  |  Voo direto', 'Passageiros', v('qtd_pessoas_volta') || '1', y);
    }
    y = dividerLine(y);

    // ── BAGAGEM ──────────────────────────────────────────────────────────────
    if (bagagens.length > 0) {
      y = sectionTitle('Bagagem', y);
      bagagens.forEach((bag, i) => {
        y = fourCols('Tipo', bag.tipo || '—', 'Quantidade', bag.qtd, 'Valor', fmtMoney(bag.valor), '', '', y);
        if (i < bagagens.length - 1) {
          doc.setDrawColor(...divider);
          doc.setLineWidth(0.2);
          doc.line(margin, y - 3, W - margin, y - 3);
        }
      });
      y = dividerLine(y);
    }

    // ── VALORES ──────────────────────────────────────────────────────────────
    y = sectionTitle('Valores da Passagem', y);
    y = fourCols('Valor Pix', fmtMoney(v('valor_passagem_pix')), 'Valor Parcelado', fmtMoney(v('valor_passagem_parcelado')), 'Qtd. Parcelas', v('qtd_parcelas') || '1', '', '', y);
    y = dividerLine(y);

    // ── OBSERVAÇÕES ───────────────────────────────────────────────────────────
    const obs = v('observacoes');
    if (obs) {
      y = sectionTitle('Observações', y);
      setFont(9, 'normal', dark);
      const lines = doc.splitTextToSize(obs, W - margin * 2 - 4);
      doc.text(lines, margin + 2, y);
      y += lines.length * 5 + 4;
    }

    // ── FOOTER ────────────────────────────────────────────────────────────────
    const totalPages = doc.getNumberOfPages();
    for (let p = 1; p <= totalPages; p++) {
      doc.setPage(p);
      doc.setFillColor(...light);
      doc.rect(0, pageH - 12, W, 12, 'F');
      setFont(7.5, 'normal', muted);
      doc.text('VoeMomentos - Documento gerado automaticamente. Confira os dados com sua companhia aérea.', W / 2, pageH - 5, { align: 'center' });
    }

    const nomeArquivo = `VoeMomentos_${cia || 'voo'}_${fmtDate(v('data_ida')).replace(/\//g,'-')}.pdf`;
    doc.save(nomeArquivo);
  });